  function inviteMarkup(){return `<div id="secureInviteModal" class="fixed inset-0 z-[100006] hidden items-center justify-center bg-black/95 p-3 text-white backdrop-blur-md"><section class="max-h-[94vh] w-full max-w-2xl overflow-y-auto border border-violet-500 bg-[#08070b] p-5 shadow-[0_0_36px_rgba(124,58,237,.3)]"><header class="flex items-start justify-between gap-3 border-b border-[#33284a] pb-4"><div><p id="secureInviteKind" class="text-[10px] font-bold text-violet-300">길드 초대</p><h2 id="secureInviteTitle" class="mt-1 text-xl font-black">초대 정보</h2><p class="mt-2 text-[10px] leading-relaxed text-gray-400">아래 코드·QR·링크는 갱신하기 전까지 계속 사용할 수 있어요.</p></div><button id="secureInviteClose" type="button" class="border border-[#444] bg-[#111] px-3 py-2 text-xs font-bold text-gray-300">닫기</button></header><div class="mt-5 grid gap-5 md:grid-cols-[minmax(0,1fr)_248px]"><div class="space-y-4"><label class="block text-[10px] font-bold text-gray-400">초대 코드<div class="mt-2 flex gap-2"><input id="secureInviteCode" readonly class="min-w-0 flex-1 border border-violet-500 bg-violet-950/25 p-3 text-center text-lg font-black tracking-[.2em] text-violet-100"><button id="secureInviteCopyCode" type="button" class="shrink-0 border border-violet-500 px-3 text-xs font-bold text-violet-200">코드 복사</button></div></label><label class="block text-[10px] font-bold text-gray-400">참여 링크<div class="mt-2 flex gap-2"><input id="secureInviteLink" readonly class="min-w-0 flex-1 border border-sky-700 bg-sky-950/20 p-3 text-xs text-sky-100"><button id="secureInviteCopyLink" type="button" class="shrink-0 border border-sky-600 px-3 text-xs font-bold text-sky-200">링크 복사</button></div></label><a id="secureInviteOpenLink" target="_blank" rel="noopener noreferrer" class="inline-flex items-center gap-1 text-xs font-bold text-sky-300 underline">참여 링크 새 창에서 확인</a><p id="secureInviteCopyStatus" class="min-h-5 text-[10px] leading-relaxed text-emerald-300"></p><div class="border border-amber-900/70 bg-amber-950/10 p-3 text-[10px] leading-relaxed text-amber-100"><b>초대 정보 갱신</b>을 누르면 현재 코드·QR·링크는 즉시 사용할 수 없고 새로운 세트가 만들어집니다.</div><button id="secureInviteRotate" type="button" class="w-full border border-red-600 bg-red-950/25 py-3 text-xs font-black text-red-200">초대 정보 갱신</button></div><div class="flex flex-col items-center justify-center border border-[#333] bg-white p-2 text-black"><canvas id="secureInviteQr" width="232" height="232" class="h-[232px] w-[232px] max-w-full"></canvas><b id="secureInviteQrCaption" class="mt-2 text-center text-xs">카메라로 길드 초대 코드 스캔</b><button id="secureInviteDownload" type="button" class="mt-3 w-full border border-black bg-white py-2 text-xs font-black text-black">QR 이미지 저장</button></div></div><p class="mt-4 border-t border-[#292929] pt-3 text-[9px] leading-relaxed text-gray-500">QR은 이 브라우저에서 직접 만들며 초대 정보를 외부 QR 서비스로 보내지 않아요. 공동 관리자 초대는 교사에게만 전달해 주세요.</p></section></div>`;}  function guildTrialMarkup(){return `<div id="secureGuildTrialModal" class="fixed inset-0 z-[100005] hidden items-center justify-center bg-black/95 p-4 text-white backdrop-blur-md"><section class="w-full max-w-lg border border-rose-600 bg-[#09070d] p-5 shadow-[0_0_32px_rgba(225,29,72,.28)]"><div class="flex items-start justify-between gap-3"><div><p class="text-[10px] font-bold text-rose-300">길드 마스터의 시련</p><h2 id="secureGuildTrialTitle" class="mt-1 text-lg font-extrabold">오답 정복 시련</h2></div><div class="text-right"><p id="secureGuildTrialReward" class="text-xs font-bold text-yellow-300"></p><p id="secureGuildTrialHints" class="mt-1 text-[10px] text-sky-300"></p></div></div><div class="mt-4 h-1.5 bg-[#24151d]"><div id="secureGuildTrialProgress" class="h-full bg-rose-500" style="width:0%"></div></div><div id="secureGuildTrialQuestionArea" class="mt-5"><div class="flex items-center justify-between gap-2"><span id="secureGuildTrialCounter" class="text-[10px] text-gray-400"></span><span id="secureGuildTrialType" class="text-[10px] font-bold text-rose-300"></span></div><p id="secureGuildTrialPrompt" class="my-5 min-h-12 whitespace-pre-line text-center text-lg font-extrabold"></p><div id="secureGuildTrialChoices" class="grid grid-cols-2 gap-2"></div><div id="secureGuildTrialInputArea" class="hidden gap-2"><input id="secureGuildTrialInput" autocomplete="off" autocapitalize="none" spellcheck="false" class="min-w-0 flex-1 border border-[#3c3c3c] bg-[#171717] p-3 text-sm text-white" placeholder="영어 철자를 입력하세요"><button id="secureGuildTrialSubmit" type="button" class="border border-rose-500 bg-rose-950/50 px-4 text-xs font-bold">확인</button></div><p id="secureGuildTrialFeedback" class="mt-3 min-h-8 text-center text-xs text-gray-400"></p><div class="mt-3 flex justify-center"><button id="secureGuildTrialHint" type="button" class="border border-sky-600 bg-sky-950/30 px-4 py-2 text-xs font-bold text-sky-200">힌트 사용</button></div></div><div id="secureGuildTrialRoundResult" class="mt-5 hidden text-center"><h3 id="secureGuildTrialResultTitle" class="text-lg font-extrabold text-yellow-300"></h3><p id="secureGuildTrialResultText" class="mt-2 text-xs leading-relaxed text-gray-300"></p><button id="secureGuildTrialAction" type="button" class="mt-4 w-full border border-yellow-500 bg-yellow-950/30 py-3 text-sm font-bold text-yellow-200"></button></div><p class="mt-4 border-t border-[#30202a] pt-3 text-[10px] leading-relaxed text-gray-500">시련은 오프라인 보상을 받은 뒤 시작됩니다. 틀린 단어는 재시험으로 다시 정복하며, 완료하지 못하면 다음 접속에서 시련을 다시 시작합니다.</p></section></div>`;}  let guildStream=null,guildDetector=null,guildScanFrame=0;
  function stopGuildScan(){if(guildScanFrame){cancelAnimationFrame(guildScanFrame);guildScanFrame=0;}const video=$('secureGuildCamera');if(video)video.srcObject=null;if(guildStream){guildStream.getTracks().forEach(track=>track.stop());guildStream=null;}guildDetector=null;const wrap=$('secureGuildCameraWrap');if(wrap)wrap.classList.add('hidden');}
  function closeGuildJoin(){stopGuildScan();hide('secureGuildModal');}
  // QRCode Generator 2.0.4 (MIT): 초대 정보는 외부 QR 서비스로 전송하지 않고 이 기기에서 그립니다.
  let currentInvite=null,pendingStudentInviteCode='',pendingManagerInviteCode='';
  function drawInviteQr(value){
    const canvas=$('secureInviteQr');
    if(!canvas)return;
    if(typeof window._qrCodeGenerator!=='function')throw new Error('QR 생성 모듈을 불러오지 못했어요. 페이지를 새로고침해 주세요.');
    const qr=window._qrCodeGenerator(0,'M');
    qr.addData(String(value||''));
    qr.make();
    const moduleCount=qr.getModuleCount(),quiet=4,moduleSize=Math.max(4,Math.floor(232/(moduleCount+quiet*2))),size=(moduleCount+quiet*2)*moduleSize;
    canvas.width=size;canvas.height=size;
    const context=canvas.getContext('2d');
    context.imageSmoothingEnabled=false;context.fillStyle='#fff';context.fillRect(0,0,size,size);context.fillStyle='#000';
    for(let row=0;row<moduleCount;row+=1)for(let col=0;col<moduleCount;col+=1)if(qr.isDark(row,col))context.fillRect((col+quiet)*moduleSize,(row+quiet)*moduleSize,moduleSize,moduleSize);
  }
  function inviteLink(code,type='student'){const url=new URL(location.origin+location.pathname);url.hash=`${type==='manager'?'managerCode':'code'}=${encodeURIComponent(code)}`;return url.toString();}
  async function copyInviteField(id,label){const input=$(id),status=$('secureInviteCopyStatus');if(!input)return false;input.focus();input.select();input.setSelectionRange?.(0,input.value.length);let copied=false;try{await navigator.clipboard.writeText(input.value);copied=true;}catch{try{copied=document.execCommand('copy');}catch{copied=false;}}if(status)status.textContent=copied?`${label}을(를) 복사했어요.`:`자동 복사가 차단됐어요. 선택된 ${label}을(를) 직접 복사해 주세요.`;return copied;}
  function closeInvite(){hide('secureInviteModal');currentInvite=null;}
  async function showInvite(invite,type,classId){const code=String(invite?.code||'').toUpperCase(),link=inviteLink(code,type);currentInvite={...invite,type,classId,link};$('secureInviteKind').textContent=type==='manager'?'공동 관리자 초대':'길드원 초대';$('secureInviteTitle').textContent=type==='manager'?'공동 관리자 초대 정보':'길드원 초대 정보';$('secureInviteCode').value=code;$('secureInviteLink').value=link;$('secureInviteOpenLink').href=link;$('secureInviteQrCaption').textContent=type==='manager'?'QR에서 공동 관리자 코드 확인':'게임 카메라로 길드 초대 코드 스캔';$('secureInviteCopyStatus').textContent='현재 초대 정보는 갱신하기 전까지 계속 사용할 수 있어요.';drawInviteQr(code);show('secureInviteModal');await copyInviteField('secureInviteCode','초대 코드');}
  function downloadInviteQr(){if(!currentInvite)return;const canvas=$('secureInviteQr'),anchor=document.createElement('a');anchor.download=`voca-hero-${currentInvite.type}-invite-${currentInvite.code}.png`;anchor.href=canvas.toDataURL('image/png');anchor.click();}
  async function rotateCurrentInvite(){if(!currentInvite)return;const rotate=async()=>{try{const {invite}=await teacherRequest('createInvite',{classId:currentInvite.classId,type:currentInvite.type,rotate:true});await showInvite(invite,currentInvite.type,currentInvite.classId);toast('새 초대 코드·QR·링크를 만들었어요.');}catch(error){alertError(error);}};const message='초대 정보를 갱신하면 지금 보이는 코드·QR·링크는 즉시 사용할 수 없어요.<br><br>새 초대 정보로 바꿀까요?';if(typeof window.showConfirm==='function')window.showConfirm(message,rotate,null,{icon:'🔄',title:'초대 정보 갱신',yesLabel:'새로 만들기',noLabel:'취소'});else rotate();}
  function captureInviteFromLocation(){const hash=location.hash.replace(/^#/,'');if(!hash.includes('='))return;const params=new URLSearchParams(hash);pendingStudentInviteCode=scannedGuildCode(params.get('code'));pendingManagerInviteCode=scannedGuildCode(params.get('managerCode'));if(pendingStudentInviteCode||pendingManagerInviteCode)history.replaceState(null,'',location.pathname+location.search);}
  function openInviteFromLocation(){if(!account||pendingStudentInviteCode.length<6)return;openGuildJoin();showGuildJoinControls();$('secureGuildModalTitle').textContent='초대 링크로 길드 가입';$('secureGuildCode').value=pendingStudentInviteCode;pendingStudentInviteCode='';}
  function openManagerInviteFromLocation(){if(pendingManagerInviteCode.length<6)return;openTeacher();$('secureManagerCode').value=pendingManagerInviteCode;if(!$('secureTeacherDashboard').classList.contains('hidden'))switchTeacherTab('create');}
