  async function finishStudentGoogleLink(){try{const auth=await activeStudentAuth(true),sourceUser=auth.currentUser,sourceUid=sourceUser?.uid;if(!sourceUser||!sourceUid)throw new Error('현재 게임 기록을 확인하지 못했어요.');await save(true);try{await window._fbLinkWithPopup(auth,window._fbStudentGoogleProvider);syncStudentAuthUI();toast('Google 계정 연결이 완료됐어요. 다른 기기에서도 이어할 수 있어요.');}catch(error){if(error?.code!=='auth/credential-already-in-use')throw error;const sourceToken=await sourceUser.getIdToken(true);await window._signInWithPopup(auth,window._fbStudentGoogleProvider);const {account:data}=await request(studentApi,{action:'claimGoogleLink',sourceUid,sourceToken},auth);clearLegacy();apply(await withAssignedWordPack(data));syncStudentAuthUI();window.showAlert?.('이전 버전의 Google 연결 기록을<br><b>새 보안 계정 연결로 안전하게 옮겼어요.</b><br><br>이제 다른 기기에서도 Google로 이어할 수 있어요.','G','Google 연결 완료');}}catch(error){alertError(error);}}
