  async function finishStudentGoogleUnlink(){try{const auth=await activeStudentAuth(true),beforeUid=auth.currentUser?.uid;if(!beforeUid||!studentGoogleLinked())throw new Error('연결된 Google 계정을 찾지 못했어요.');await save(true);try{await window._fbUnlink(auth.currentUser,'google.com');}catch(error){if(error?.code!=='auth/requires-recent-login')throw error;await window._fbReauthenticateWithPopup(auth.currentUser,window._fbStudentGoogleProvider);await window._fbUnlink(auth.currentUser,'google.com');}if(!auth.currentUser||auth.currentUser.uid!==beforeUid)throw new Error('연결 해제 후 현재 기기의 게스트 계정을 확인하지 못했어요. 안전을 위해 페이지를 닫지 말고 새로고침해 주세요.');syncStudentAuthUI();window.showAlert?.('Google 계정 연결을 해제했어요.<br><br><span class="text-yellow-200">이 용사의 기록은 이제 이 기기에서만 이어할 수 있어요.</span><br>브라우저 데이터 삭제·기기 변경 전에는 다시 Google에 연결해 주세요.<br><br>이제 다른 게스트 계정에서 같은 Google 계정을 연결할 수 있어요.','G','Google 연결 해제 완료');}catch(error){alertError(error);}}
