  async function secureWorldBossStatus(force=false){if(!force&&bossStatusCache&&Date.now()-bossStatusCachedAt<15000)return applyBossStatus(bossStatusCache);if(bossStatusPromise)return bossStatusPromise;bossStatusPromise=request(worldBossApi,{action:'status'},window._fbAuth).then(({boss})=>{bossStatusCache=boss;bossStatusCachedAt=Date.now();return applyBossStatus(boss);}).finally(()=>{bossStatusPromise=null;});return bossStatusPromise;}
  async function secureWorldBossWeeklyReward(){if(weeklyRewardChecked)return null;weeklyRewardChecked=true;let reward;try{({reward}=await request(worldBossApi,{action:'weeklyReward'},window._fbAuth));}catch(error){weeklyRewardChecked=false;throw error;}if(!reward?.rewardFp&&!reward?.gotTitle)return reward;gameState.masteryPoints=Number(gameState.masteryPoints||0)+Number(reward.rewardFp||0);if(account?.state)account.state.masteryPoints=gameState.masteryPoints;if(reward.gotTitle){gameState.unlockedTitles=Array.from(new Set([...(gameState.unlockedTitles||[]),'수호신']));if(account?.state)account.state.unlockedTitles=gameState.unlockedTitles;}window.refreshStateVisuals?.();const resultText=reward.defeated?'완전 승리':'부분 보상';const titleText=reward.gotTitle?'<br><b class="text-yellow-300">누적 피해 1위로 [수호신] 칭호를 획득했어요!</b>':'';window.showAlert?.(`지난 주 월드보스 결산: ${resultText}<br><b>+${Number(reward.rewardFp).toLocaleString()} FP</b>${titleText}`,'🏆','월드보스 주간 결산');return reward;}
