      const row=document.createElement('div'),check=document.createElement('input'),identity=document.createElement('div'),name=document.createElement('b'),detail=document.createElement('small'),stage=document.createElement('span'),points=document.createElement('span'),accuracy=document.createElement('span'),report=document.createElement('button');
