      check.type='checkbox';check.dataset.memberId=member.memberId;check.onchange=updateTeacherSelectionHint;
      identity.className='min-w-0';name.className='block truncate font-bold text-white';name.textContent=member.nickname+' · '+Number(member.learningGrade||4)+'학년';
      detail.className='mt-1 block truncate text-[8px] text-gray-500';detail.textContent='정답 '+Number(member.totalCorrect||0).toLocaleString()+' · 숙련 '+Number(member.masteredCount||0).toLocaleString()+' · 최근 '+(member.lastActiveAt?new Date(member.lastActiveAt).toLocaleDateString('ko-KR'):'기록 없음');
      identity.append(name,detail);stage.className='text-gray-300';stage.textContent='S'+Number(member.stage||1);points.className='text-right font-black text-yellow-300';points.textContent=Number(member.guildPoints||0).toLocaleString();accuracy.className='text-right text-emerald-300';accuracy.textContent=Number(member.accuracy||0).toFixed(1)+'%';
      report.type='button';report.className='border border-yellow-700 px-2 py-1 text-[9px] text-yellow-300';report.textContent='보기';report.onclick=()=>loadTeacherMemberReport(member.memberId);
