  async function init(){build();try{const auth=await activeStudentAuth();if(typeof auth.authStateReady==='function')await auth.authStateReady();if(!auth.currentUser)await window._fbSignInAnonymously(auth);const returningUser=hasLocalStudentAccount();if(returningUser)beginGameEntry('✨ 영혼석에서 모험 기록을 불러오는 중...');const {account:data}=await request(studentApi,{action:'load'},auth);if(data){if(!returningUser)beginGameEntry('✨ 영혼석에서 모험 기록을 불러오는 중...');clearLegacy();apply(await withAssignedWordPack(data));toast(`${data.nickname}님, 다시 만나서 반가워요. 영웅과 함께 전설의 여정을 떠나봐요.`);}else{localStorage.removeItem(studentAccountMarker);cancelGameEntry('secureWelcomeModal');showMigrationNotice();}}catch(error){console.error(error);cancelGameEntry('secureWelcomeModal');alertError(new Error('안전한 계정을 준비하지 못했어요. 잠시 후 페이지를 새로고침해 주세요.'));}}  function openTeacher(){show('secureTeacherModal');if(window._fbTeacherAuth?.currentUser){$('secureTeacherLoginBox').classList.add('hidden');$('secureTeacherDashboard').classList.remove('hidden');switchTeacherTab('overview');Promise.all([refreshClasses(),loadTeacherProfile(true)]).then(()=>refreshTeacherSchoolData()).catch(alertError);}}
